{
  "avaliacoes": [
    {
      "id": "Ea5414a2ffa6198a3",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "A fonte define perigo de red zone como a situação em que o trabalhador está no trajeto direto de um objeto ou da liberação de energia associada, podendo ser atingido, prensado, perfurado, esmagado ou ficar preso entre objetos durante operações de içamento.",
          "trechos": [
            "Ea5414a2ffa6198a3:700:1400"
          ],
          "condicoes": [
            "em atividades offshore com cargas, linhas oscilantes, máquinas e outros perigos mecânicos",
            "quando houver exposição direta ao movimento da carga ou a energias liberadas pelo sistema"
          ],
          "limites": [
            "a definição e os exemplos vêm de alerta de segurança da BSEE, de jurisdição dos EUA",
            "o trecho não fornece método formal para delimitar fisicamente cada red zone"
          ]
        },
        {
          "proposicao": "A fonte recomenda estabelecer barricadas ou áreas de red zone para restringir o acesso de trabalhadores a locais onde possam ficar expostos ao perigo, como prática para eliminar incidentes desse tipo.",
          "trechos": [
            "Ea5414a2ffa6198a3:1400:2099"
          ],
          "condicoes": [
            "quando existirem áreas em que o trabalhador possa ficar exposto ao dano potencial durante o içamento",
            "na organização do espaço de trabalho e do acesso de pessoal"
          ],
          "limites": [
            "trata-se de prática recomendada, não de requisito brasileiro nesta extração",
            "o trecho não define critérios de dimensionamento, sinalização ou fiscalização dessas barreiras"
          ]
        },
        {
          "proposicao": "A fonte recomenda desenvolver e aplicar regras de red zone e tratar taglines com cuidado, considerando que elas próprias podem se tornar perigosas quando enroscam, ficam muito próximas da carga ou são usadas sem necessidade; também menciona adequar o comprimento e usá-las apenas quando necessárias ao trabalho.",
          "trechos": [
            "Ea5414a2ffa6198a3:1400:2099"
          ],
          "condicoes": [
            "quando forem empregadas taglines para auxiliar o controle da carga",
            "quando houver áreas barricadas ou designadas como de maior risco"
          ],
          "limites": [
            "a fonte não fornece valores numéricos de comprimento nem critérios operacionais detalhados para seleção de tagline",
            "o trecho recuperado termina antes da conclusão de uma recomendação adicional sobre posicionamento das mãos"
          ]
        }
      ]
    },
    {
      "id": "E965a088e36b2bb21",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "A fonte recomenda identificar pontos potenciais de contato e enroscamento quando se trabalha próximo a equipamentos e estruturas, incorporando ações de mitigação, inclusive a colocação de observadores adicionais nesses pontos quando apropriado.",
          "trechos": [
            "E965a088e36b2bb21:0:700"
          ],
          "condicoes": [
            "quando a movimentação da carga ocorrer perto de equipamentos ou estruturas da instalação",
            "especialmente em áreas com possibilidade de contato ou snag points"
          ],
          "limites": [
            "é recomendação de alerta de segurança, não resultado experimental controlado",
            "o trecho não define quantitativo, posicionamento ou competência mínima dos observadores adicionais"
          ]
        },
        {
          "proposicao": "A fonte recomenda que todos os envolvidos participem de reunião pré-tarefa ou toolbox talk documentada, revisem a JSA e compreendam perigos, políticas, procedimentos, contingências e comunicações antes da operação de içamento.",
          "trechos": [
            "E965a088e36b2bb21:0:700",
            "E965a088e36b2bb21:700:1394"
          ],
          "condicoes": [
            "para pessoal próprio e contratado envolvido na operação de içamento",
            "antes do início da atividade"
          ],
          "limites": [
            "o trecho não detalha formato, duração ou conteúdo mínimo obrigatório da toolbox",
            "o documento informa circunstâncias e recomendações da BSEE, não requisito legal brasileiro"
          ]
        },
        {
          "proposicao": "A fonte recomenda incorporar comunicações de verificação do movimento da carga entre rigger e operador, com confirmações incrementais, fazer visualização passo a passo da movimentação e revisar drop zones e safe zones, com atenção especial a blind lifts e folgas estreitas.",
          "trechos": [
            "E965a088e36b2bb21:700:1394"
          ],
          "condicoes": [
            "durante o planejamento e a execução do içamento",
            "especialmente em blind lifts ou quando não for possível evitar folga estreita"
          ],
          "limites": [
            "os comandos citados são exemplos de comunicação, não protocolo universal obrigatório",
            "o trecho não especifica responsabilidades detalhadas entre sinaleiro, rigger e supervisor"
          ]
        }
      ]
    },
    {
      "id": "Ed1078c0e7e3cfbc1",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "A fonte orienta verificar como o responsável assegura que cada pessoa envolvida no içamento compreende claramente seu próprio papel, o papel dos demais, a forma de comunicação do plano de içamento à equipe e as expectativas quanto ao uso de tag lines.",
          "trechos": [
            "Ed1078c0e7e3cfbc1:0:698"
          ],
          "condicoes": [
            "na fase de planejamento e implementação da operação de içamento",
            "ao comunicar o lifting plan à equipe"
          ],
          "limites": [
            "é um template de inspeção e perguntas de verificação, não descrição de um processo único obrigatório",
            "o trecho não define método pedagógico ou critério de aceitação da compreensão da equipe"
          ]
        },
        {
          "proposicao": "Quando rádios forem usados, a fonte orienta que exista protocolo ou sistema claro e eficaz, compreendido pelas pessoas competentes, podendo incluir canal dedicado entre operador e sinaleiro, protocolo para falha de comunicação, identificação do emissor e do destinatário e instruções claras e sem ambiguidade.",
          "trechos": [
            "Ed1078c0e7e3cfbc1:0:698",
            "Ed1078c0e7e3cfbc1:698:1394"
          ],
          "condicoes": [
            "quando a operação utilizar comunicação por rádio",
            "durante instruções de guindaste ou guincho e coordenação do içamento"
          ],
          "limites": [
            "a própria fonte usa formulações exemplificativas como may include, logo não fecha um protocolo único",
            "documento de orientação do Reino Unido, sem conversão automática em requisito brasileiro"
          ]
        },
        {
          "proposicao": "A fonte orienta que as comunicações contemplem operações normais, condições anormais possíveis, interrupções de trabalho e interação com todo o pessoal e terceiros que possam interferir na operação; também indica verificar a estrutura e a qualidade das passagens de serviço ou handover.",
          "trechos": [
            "Ed1078c0e7e3cfbc1:698:1394",
            "Ed1078c0e7e3cfbc1:1394:2090",
            "Ed1078c0e7e3cfbc1:2090:2314"
          ],
          "condicoes": [
            "em operações com múltiplos participantes ou troca de equipes",
            "quando houver necessidade de handover em trabalho contínuo ou com nova tripulação"
          ],
          "limites": [
            "o trecho trata de critérios de inspeção e perguntas orientadoras, não de evidência experimental",
            "não descreve um formato obrigatório de registro, livro de handover ou auditoria"
          ]
        }
      ]
    },
    {
